//! Additional RTL compatibility helpers with caller-owned buffers and fixed ABI layouts.
use super::{UnicodeString};
const SUCCESS:i32=0;const INVALID:i32=0xC000000Du32 as i32;const INVALID_SD:i32=0xC0000079u32 as i32;
#[repr(C)] pub struct GenericMapping{pub generic_read:u32,pub generic_write:u32,pub generic_execute:u32,pub generic_all:u32}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_map_generic_mask(mask:*mut u32,mapping:*const GenericMapping){if mask.is_null()||mapping.is_null(){return;}let m=unsafe{&*mapping};let mut v=unsafe{*mask};if v&0x80000000!=0{v=(v&!0x80000000)|m.generic_read;}if v&0x40000000!=0{v=(v&!0x40000000)|m.generic_write;}if v&0x20000000!=0{v=(v&!0x20000000)|m.generic_execute;}if v&0x10000000!=0{v=(v&!0x10000000)|m.generic_all;}unsafe{*mask=v;}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_map_security_error_to_nt_status(error:u32)->i32{match error{0=>0,2|3=>0xC0000034u32 as i32,5=>0xC0000022u32 as i32,6=>0xC0000008u32 as i32,8|14=>0xC0000017u32 as i32,87=>INVALID,112=>0xC000007Fu32 as i32,122=>0xC0000023u32 as i32,183=>0xC0000035u32 as i32,995=>0xC0000120u32 as i32,998=>0xC0000005u32 as i32,1005=>0xC0000102u32 as i32,_=>0xC0000001u32 as i32}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_is_api_set_implemented(_name:*const UnicodeString)->u8{0}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_is_functionality_available(_id:u32)->u8{0}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_is_name_legal_dos8_dot3(name:*const UnicodeString,oem:*mut super::AnsiString,contains_spaces:*mut u8)->u8{if name.is_null(){return 0;}let s=unsafe{&*name};if s.length%2!=0||(s.length>0&&s.buffer.is_null()){return 0;}let n=(s.length/2) as usize;let mut base=0usize;let mut ext=0usize;let mut dot=false;let mut spaces=false;for i in 0..n{let c=unsafe{*s.buffer.add(i)};if c==32{spaces=true;continue;}if c==46{if dot||base==0{return 0;}dot=true;continue;}if c>127||!(((48..=57).contains(&c)||(65..=90).contains(&c)||(97..=122).contains(&c))||matches!(c,33|35|36|37|38|39|40|41|45|64|94|95|96|123|125|126)){return 0;}if dot{ext+=1;}else{base+=1;}}if base>8||ext>3{return 0;}if !oem.is_null(){let d=unsafe{&mut *oem};if (d.maximum_length as usize)<n|| (n>0&&d.buffer.is_null()){return 0;}for i in 0..n{let c=unsafe{*s.buffer.add(i)};unsafe{*d.buffer.add(i)=if c<=255{c as u8}else{b'?'};}}d.length=n as u16;}if !contains_spaces.is_null(){unsafe{*contains_spaces=spaces as u8;}}if spaces{0}else{1}}
#[repr(C)] pub struct RtlOsVersionInfoExW{pub size:u32,pub major:u32,pub minor:u32,pub build:u32,pub platform:u32,pub service_pack:[u16;128],pub service_pack_major:u16,pub service_pack_minor:u16,pub suite_mask:u16,pub product_type:u8,pub reserved:u8}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_get_version(info:*mut RtlOsVersionInfoExW)->i32{if info.is_null(){return INVALID;}let x=unsafe{&mut *info};if x.size<276{return INVALID;}x.major=10;x.minor=0;x.build=26100;x.platform=2;x.service_pack=[0;128];if x.size>=284{x.service_pack_major=0;x.service_pack_minor=0;x.suite_mask=0;x.product_type=1;x.reserved=0;}SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_valid_relative_security_descriptor(sd:*const u8,length:u32,required:u32)->u8{if sd.is_null()||length<20||unsafe{*sd}!=1{return 0;}let control=unsafe{*(sd.add(2) as *const u16)};if control&0x8000==0{return 0;}let offsets=[unsafe{*(sd.add(4) as *const u32)},unsafe{*(sd.add(8) as *const u32)},unsafe{*(sd.add(12) as *const u32)},unsafe{*(sd.add(16) as *const u32)}];if required&1!=0&&offsets[0]==0{return 0;}if required&2!=0&&offsets[1]==0{return 0;}if required&4!=0&&control&0x0004==0{return 0;}if required&8!=0&&control&0x0010==0{return 0;}for i in 0..4{let off=offsets[i] as usize;if off==0{continue;}if off<20||off>=length as usize{return 0;}let remaining=length as usize-off;if i<2{let p=unsafe{sd.add(off) as *const super::sid::SidHeader};let n=unsafe{super::sid::rtl_length_sid(p)} as usize;if n==0||n>remaining{return 0;}}else{if remaining<8{return 0;}let p=unsafe{sd.add(off) as *const super::acl::RtlAcl};let n=unsafe{(*p).size as usize};if n<8||n>remaining||unsafe{super::acl::rtl_valid_acl(p)}==0{return 0;}}}1}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_get_default_code_page(ansi:*mut u16,oem:*mut u16){if !ansi.is_null(){unsafe{*ansi=1252;}}if !oem.is_null(){unsafe{*oem=437;}}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_is_nt_ddi_version_available_ex(version:u32)->u8{(version<=0x0A000000) as u8}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_is_valid_oem_character_ex(c:u16)->u8{(c>0&&c<=255) as u8}

#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_is_non_empty_directory_reparse_point_allowed()->u8{0}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_is_partial_placeholder(_handle:*mut core::ffi::c_void)->u8{0}

#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_is_partial_placeholder_file_handle(_handle:*mut core::ffi::c_void)->u8{0}
